import json, math, itertools
from datetime import datetime

KIT='/home/hatch/workspace/makefun-watch/kits/gta6-twitch-ccu-forecast-01/gta6-twitch-ccu-forecast-01-kit/input/'
LEVELS=[0.05,0.25,0.5,0.75,0.95]
Z=[-1.645,-0.674,0.0,0.674,1.645]
ANS={k:{int(h):v for h,v in a.items()} for k,a in json.load(open('/tmp/gta6exp/practice_answers.json')).items()}

def pt(t): return datetime.fromisoformat(t.replace('Z','+00:00'))

def day_series(comp):
    ds=pt(comp['day_start']); out={}
    for r in comp.get('hourly') or []:
        try: h=(pt(r['from'])-ds).total_seconds()/3600; v=r['viewers']
        except Exception: continue
        if 0<=h<24 and abs(h-round(h))<1e-9 and v and v>0: out[int(h)+1]=float(v)
    return out

def tier(comp):
    u=comp.get('unlock') or ''
    if 'Tier: early-access-contaminated' in u: return 'eac'
    if 'Tier: weak' in u: return 'weak'
    if 'Tier: target-history' in u: return 'target'
    if 'Tier: comparable' in u: return 'comp'
    return 'unknown'

def unlock_type(comp):
    u=(comp.get('unlock') or '').lower()
    if 'rolling' in u or 'midnight local' in u: return 'rolling'
    if 'simultaneous' in u or 'single global' in u: return 'simul'
    return 'unk'

def load_pool(casefile):
    c=json.load(open(KIT+casefile))
    pool=[]
    for comp in c['comparables']:
        s=day_series(comp)
        if 1 in s and sum(1 for h in range(2,25) if h in s)>=12:
            pool.append({'name':comp['name'],'v1':s[1],'series':s,'tier':tier(comp),'utype':unlock_type(comp)})
    return c, pool

def pinball(forecast, truth):
    # forecast: {hour: [q05..q95]}; truth: {hour: viewers}
    tot=0.0; n=0
    for h,y in truth.items():
        if h<2: continue
        y=max(1.0,y)
        for tau,q in zip(LEVELS, forecast[h]):
            d=math.log(y)-math.log(max(1.0,q))
            tot+=2*max(tau*d,(tau-1)*d); n+=1
    return tot/n

def baseline(p1):
    return {h:[p1*math.exp(z*0.15*math.sqrt(h-1)) for z in Z] for h in range(2,25)}

def wquant(pairs, tau):
    # pairs: list of (value, weight); linear interpolation on weighted CDF
    o=sorted(pairs); tot=sum(w for _,w in o)
    if tot<=0: return o[len(o)//2][0]
    target=tau*tot; acc=0.0; prev_v,prev_c=None,0.0
    for v,w in o:
        acc+=w
        if acc>=target:
            if prev_v is None: return v
            # interpolate between prev point and this one
            frac=(target-prev_c)/w if w>0 else 0.0
            return prev_v+frac*(v-prev_v)
        prev_v,prev_c=v,acc
    return o[-1][0]

def wmedian(pairs): return wquant(pairs,0.5)
def wsd(pairs, centre):
    tot=sum(w for _,w in pairs)
    if tot<=0 or len(pairs)<2: return 0.0
    return math.sqrt(max(0.0,sum(w*(v-centre)**2 for _,v in [(0,0)] ))) if False else math.sqrt(max(0.0,sum(w*(v-centre)**2 for v,w in pairs)/tot))

def smooth3(d):
    out={}
    for h in sorted(d):
        near=[d[x] for x in (h-1,h,h+1) if x in d]
        out[h]=sum(near)/len(near)
    return out

# ---- model factory ----
def forecast_model(p1, pool, cfg):
    # cfg: bw, tiers(set), utype_w(dict), shrink, alpha, spread_band(dict hour->scale), smooth(bool), spread_mode('emp'|'normal'), spread_scale, floor
    logp1=math.log(p1)
    ratios={h:[] for h in range(2,25)}
    for c in pool:
        if c['tier'] not in cfg['tiers']: continue
        w=math.exp(-((math.log(c['v1'])-logp1)**2)/(2*cfg['bw']**2))
        w*=cfg['utype_w'].get(c['utype'],1.0)
        for h in range(2,25):
            if h in c['series']:
                ratios[h].append((math.log(c['series'][h]/c['v1']), w))
    med={}; off={t:{} for t in LEVELS}
    for h in range(2,25):
        pairs=ratios[h]
        if not pairs: continue
        m=wmedian(pairs)
        med[h]=m
        if cfg['spread_mode']=='emp':
            for t in LEVELS: off[t][h]=wquant(pairs,t)-m
        else:
            sd=max(cfg['floor'], cfg['spread_scale']*wsd(pairs,m))
            for i,t in enumerate(LEVELS): off[t][h]=Z[i]*sd
    if not med: return baseline(p1)
    med_s=smooth3(med) if cfg['smooth'] else med
    off_s={t:(smooth3(off[t]) if cfg['smooth'] else off[t]) for t in LEVELS}
    out={}
    for h in range(2,25):
        if h not in med_s:
            out[h]=baseline(p1)[h]; continue
        band=cfg['spread_band'](h)
        qs=[]
        for i,t in enumerate(LEVELS):
            walk=Z[i]*0.15*math.sqrt(h-1)
            o=cfg['alpha']*off_s[t].get(h,0.0)*band+(1-cfg['alpha'])*walk
            qs.append(p1*math.exp(cfg['shrink']*med_s[h]+o))
        for i in range(1,5): qs[i]=max(qs[i],qs[i-1])
        out[h]=[min(max(q,0.01),1e9) for q in qs]
    return out

def loo(pool, cfg, big_only=False):
    losses=[]; big=[]
    for i,c in enumerate(pool):
        others=[x for j,x in enumerate(pool) if j!=i]
        f=forecast_model(c['v1'], others, cfg)
        truth={h:v for h,v in c['series'].items() if h>=2}
        l=pinball(f, truth)
        losses.append(l)
        if c['v1']>=50000: big.append(l)
    return sum(losses)/len(losses), (sum(big)/len(big) if big else float('nan')), len(big)

def practice(cfg):
    res={}
    for pid in ['p00','p01','p02','p03']:
        c=json.load(open(KIT+pid+'.in'))
        _,pool=load_pool(pid+'.in')
        p1=c['known'][0]['viewers']
        f=forecast_model(p1, pool, cfg)
        res[pid]=pinball(f, ANS[pid])
    res['mean']=sum(res.values())/4
    return res

BASE_CFG=dict(bw=0.7, tiers={'comp','weak','unknown'}, utype_w={}, shrink=0.85, alpha=0.85,
              spread_band=lambda h:1.0, smooth=True, spread_mode='emp', spread_scale=0.85, floor=0.15)
if __name__=='__main__':
    c,pool=load_pool('p00.in')
    print('pool size:', len(pool), 'tiers:', {t:sum(1 for x in pool if x['tier']==t) for t in ['comp','weak','eac','target','unknown']})
    print('utypes:', {t:sum(1 for x in pool if x['utype']==t) for t in ['rolling','simul','unk']})
    print('baseline LOO:', loo(pool, dict(BASE_CFG, tiers={'comp','weak','unknown'}, spread_mode='emp', alpha=0.0, shrink=0.0, smooth=False)))
    # berkah replica: all tiers, bw .7 shrink .85 alpha .85 emp smooth
    print('berkah replica LOO:', loo(pool, BASE_CFG))
    # berkahmuse replica: bw 1.0, normal spread scale .85 floor .15, no shrink/smooth/alpha
    print('berkahmuse replica LOO:', loo(pool, dict(BASE_CFG, bw=1.0, shrink=1.0, alpha=1.0, spread_mode='normal', spread_scale=0.85, smooth=False)))
    print('berkah practice:', practice(BASE_CFG))
    print('berkahmuse practice:', practice(dict(BASE_CFG, bw=1.0, shrink=1.0, alpha=1.0, spread_mode='normal', spread_scale=0.85, smooth=False)))
